function craftStudioQuoteDetails(p,recipe){var ids=[recipe.itemId,...p.materials.map(m=>m.itemId),...p.outputs.map(o=>o.itemId)];return [...new Set(ids)].map(id=>{var meta=VISION_CRAFT_DATA.items[id],q=craftStudioQuote(meta?.name,id);return q?'<p class="studio-muted">'+visionEscape(meta?.name||id)+' · base '+craftStudioMoney(q.price)+' · last sale '+craftStudioMoney(q.last_sold_price)+' · stock '+craftStudioMoney(q.stock)+' · 14-day daily average '+craftStudioMoney(q.daily_volume)+' · fetched '+visionEscape(q.updatedAt?new Date(q.updatedAt).toLocaleString():'timestamp unavailable')+'</p>':'';}).join('');}
function craftStudioAnalysis(p){if(p.missing)return '<p class="studio-warning">Complete the plan’s prices to unlock profit graphs. Quantities and shopping shortages remain usable.</p>';var scenarios=VisionCraft.scenarios(p);return '<div class="studio-waterfall">'+[['Retained proceeds',p.proceeds],['Input value + extras',p.cost],['Expected profit',p.profit]].map(([name,value])=>'<div><span>'+name+'</span><i style="width:'+Math.max(1,Math.min(100,Math.abs(value)/Math.max(1,p.proceeds,p.cost)*100))+'%;background:'+(value<0?'#ee9aaa':'#bb91ed')+'"></i><b>'+craftStudioMoney(value)+'</b></div>').join('')+'</div><h4>Production progress · modeled net silver</h4>'+craftStudioGraph(Array.from({length:25},(_,i)=>[i,p.profit*i/24]),'Expected net profit as the planned production completes')+'<h4>Sale-price sensitivity · −20% to +20%</h4>'+craftStudioGraph(scenarios.map(s=>[s.multiplier,s.profit]),'Expected profit if all sale valuations change by minus twenty to plus twenty percent')+'<p class="studio-muted">−20%: '+craftStudioMoney(scenarios[0].profit)+' · current: '+craftStudioMoney(p.profit)+' · +20%: '+craftStudioMoney(scenarios[4].profit)+'. Byproduct exchange value, when enabled, is already included once in proceeds.</p>';}
function craftStudioTree(p){var rows=p.economics,cursor=0;function branch(depth){var html='<ul>';while(cursor<rows.length&&rows[cursor].depth===depth){var row=rows[cursor++],nested=cursor<rows.length&&rows[cursor].depth>depth,label=visionEscape(row.name)+' × '+craftStudioMoney(row.quantity)+' · '+craftStudioMoney(row.owned)+' owned';html+='<li>'+(nested?'<details open><summary>'+label+' · make</summary>'+branch(depth+1)+'</details>':'<span>'+label+'</span><small>'+visionEscape(row.basis)+' · '+craftStudioMoney(row.unit)+' / unit</small>')+'</li>';}return html+'</ul>';}return '<div class="studio-dependency-tree" aria-label="Resolved material dependencies">'+branch(0)+'</div>';}
