function craftStudioWorkshopProgress(recipe,p){
 var signature=JSON.stringify([recipe.id,p.count,p.steps.map(s=>[s.recipeId,s.batches,s.expected,s.inputs.map(m=>[m.itemId,m.quantity])])]);
 var saved=craftStudioState.workshop;if(!saved||saved.signature!==signature)saved={signature,done:[]};
 var done=Array.isArray(saved.done)?saved.done.filter((v,i)=>v===i&&i<p.steps.length):[];
 // Only a consecutive prefix can be checked: prerequisite work precedes its consumer.
 var n=0;while(done.includes(n))n++;saved.done=Array.from({length:n},(_,i)=>i);craftStudioState.workshop=saved;
 return {saved,completed:n,percent:100*n/p.steps.length};
}
